import React, { useState, useMemo } from 'react';
import { Upload, X, ArrowRight, ArrowLeft, Table, CheckCircle2, AlertCircle, FileText, LayoutGrid, ListFilter, Settings2 } from 'lucide-react';
import { AnalysisState, ImportMode, DataStructure, RankSource, ColumnMapping, StudentRecord, ScoreSnapshot } from '../types';

interface ImportWizardProps {
  onComplete: (data: AnalysisState) => void;
  onCancel: () => void;
  currentData: AnalysisState | null;
}

const ImportWizard: React.FC<ImportWizardProps> = ({ onComplete, onCancel, currentData }) => {
  const [step, setStep] = useState(1);
  const [files, setFiles] = useState<File[]>([]);
  const [mode, setMode] = useState<ImportMode>('complete');
  const [structure, setStructure] = useState<DataStructure>('multi-file-single');
  const [rankSource, setRankSource] = useState<RankSource>('recalculate');
  const [periodNamesInput, setPeriodNamesInput] = useState<string>('');

  const [headers, setHeaders] = useState<string[]>([]);
  const [mapping, setMapping] = useState<ColumnMapping>({
    name: '',
    class: '',
    subjects: {},
    subjectRanks: {}
  });

  const [loading, setLoading] = useState(false);

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (!e.target.files || e.target.files.length === 0) return;
    const newFiles = Array.from(e.target.files) as File[];
    setFiles(prev => [...prev, ...newFiles]);

    const reader = new FileReader();
    reader.onload = (evt) => {
      const bstr = evt.target?.result;
      const wb = (window as any).XLSX.read(bstr, { type: 'binary' });
      const ws = wb.Sheets[wb.SheetNames[0]];

      const rows = (window as any).XLSX.utils.sheet_to_json(ws, { header: 1 });
      if (rows.length > 0) {
        const firstRow = rows.find((r: any[]) => r && r.length > 0) as any[];
        if (!firstRow) return;

        const foundHeaders = firstRow.map(h => String(h || '').trim()).filter(h => h.length > 0);
        setHeaders(foundHeaders);

        const autoMapping: ColumnMapping = {
          name: '',
          class: '',
          subjects: {},
          subjectRanks: {}
        };

        // Improved Chinese and English header detection
        foundHeaders.forEach(h => {
          const lower = h.toLowerCase();
          if (!autoMapping.name && (lower === '姓名' || lower === 'name' || lower.includes('学生姓名') || lower === '学生')) {
            autoMapping.name = h;
          } else if (!autoMapping.class && (lower === '班级' || lower === '班' || lower === 'class' || lower.includes('班级名称') || lower === '班别')) {
            autoMapping.class = h;
          }
        });

        foundHeaders.forEach(h => {
          if (h === autoMapping.name || h === autoMapping.class) return;
          const lower = h.toLowerCase();
          const isRankCol = lower.includes('名') || lower.includes('次') || lower.includes('rank') || lower === '排名';
          const isIdCol = lower.includes('号') || lower.includes('学') || lower.includes('id') || lower === '学籍';
          const isStatusCol = lower.includes('上线') || lower.includes('状态') || lower === '等级' || lower === '录取';

          if (!isRankCol && !isIdCol && !isStatusCol) {
            autoMapping.subjects[h] = h;
          }

          // Auto-pick rank column if source is imported
          if (!autoMapping.totalRank && (lower === '级名' || lower === '年级排名' || lower === '全校名次' || lower === '总分名次' || lower === 'total rank')) {
            autoMapping.totalRank = h;
          }
        });

        setMapping(autoMapping);
      }
    };
    reader.readAsBinaryString(newFiles[0]);
  };

  const handleFinalImport = async () => {
    setLoading(true);
    try {
      const allSubjects = Object.keys(mapping.subjects);
      const studentMap = new Map<string, { class: string; history: ScoreSnapshot[] }>();

      // Load existing state to allow incremental updates
      if (currentData) {
        currentData.students.forEach(s => {
          studentMap.set(s.name, { class: s.class, history: [...s.history] });
        });
      }

      const getFileContent = (file: File) => new Promise<any[]>((resolve) => {
        const reader = new FileReader();
        reader.onload = (e) => {
          const wb = (window as any).XLSX.read(e.target?.result, { type: 'binary' });
          resolve((window as any).XLSX.utils.sheet_to_json(wb.Sheets[wb.SheetNames[0]], { defval: null }));
        };
        reader.readAsBinaryString(file);
      });

      const createSnapshot = (row: any, period: string, subs: string[]): ScoreSnapshot => {
        const scores: Record<string, number> = {};
        const ranks: Record<string, number> = {};
        let total = 0;

        subs.forEach(sub => {
          const val = row[mapping.subjects[sub]];
          const score = typeof val === 'number' ? val : parseFloat(String(val || '0')) || 0;
          scores[sub] = score;
          total += score;

          if (rankSource === 'imported' && mapping.subjectRanks[sub]) {
            const rankVal = row[mapping.subjectRanks[sub]];
            ranks[sub] = typeof rankVal === 'number' ? rankVal : parseInt(String(rankVal || '0')) || 0;
          }
        });

        return {
          period,
          scores,
          ranks: rankSource === 'imported' ? ranks : undefined,
          totalScore: parseFloat(total.toFixed(2)),
          averageScore: parseFloat((total / (subs.length || 1)).toFixed(2)),
          schoolRank: rankSource === 'imported' && mapping.totalRank ? parseInt(String(row[mapping.totalRank] || '0')) : undefined,
          isComplete: mode === 'complete'
        };
      };

      if (structure === 'multi-file-single') {
        for (const file of files) {
          const periodName = file.name.replace(/\.[^/.]+$/, "").replace(/[_-]/g, " ");
          const content = await getFileContent(file);

          content.forEach((row: any) => {
            const name = String(row[mapping.name] || '').trim();
            if (!name || name === 'undefined' || name === mapping.name || name.toLowerCase() === 'name') return;

            const snapshot = createSnapshot(row, periodName, allSubjects);
            if (!studentMap.has(name)) {
              studentMap.set(name, { class: String(row[mapping.class] || '').trim(), history: [] });
            }
            const info = studentMap.get(name)!;
            const existingIdx = info.history.findIndex(h => h.period === periodName);
            if (existingIdx >= 0) info.history[existingIdx] = snapshot;
            else info.history.push(snapshot);
          });
        }
      } else {
        // Single File Summary Table - Multiple Rows per student
        const content = await getFileContent(files[0]);
        const periods = periodNamesInput.split(',').map(s => s.trim()).filter(Boolean);

        // Group rows by student name
        const studentRows = new Map<string, { class: string, rows: any[] }>();
        content.forEach(row => {
          const name = String(row[mapping.name] || '').trim();
          if (!name || name === 'undefined' || name === mapping.name || name.toLowerCase() === 'name') return;

          if (!studentRows.has(name)) {
            studentRows.set(name, { class: String(row[mapping.class] || '').trim(), rows: [] });
          }
          studentRows.get(name)!.rows.push(row);
        });

        // Use period names from input or default numbering
        const maxExams = Array.from(studentRows.values()).reduce((max, s) => Math.max(max, s.rows.length), 0);
        const finalPeriodNames = Array.from({ length: maxExams }, (_, i) => periods[i] || `Exam ${i + 1}`);

        studentRows.forEach((data, name) => {
          if (!studentMap.has(name)) {
            studentMap.set(name, { class: data.class, history: [] });
          }
          const info = studentMap.get(name)!;

          data.rows.forEach((row, idx) => {
            const periodName = finalPeriodNames[idx];
            const snapshot = createSnapshot(row, periodName, allSubjects);

            // Deduplicate period records
            const existingIdx = info.history.findIndex(h => h.period === periodName);
            if (existingIdx >= 0) {
              info.history[existingIdx] = snapshot;
            } else {
              info.history.push(snapshot);
            }
          });
        });
      }

      // Final transformation to StudentRecord array
      const students: StudentRecord[] = Array.from(studentMap.entries()).map(([name, info], index) => {
        // Sort history by the order they were imported or by period names
        const latest = info.history[info.history.length - 1];
        return {
          id: `s-${index}`,
          name,
          class: info.class,
          scores: latest.scores,
          totalScore: latest.totalScore,
          averageScore: latest.averageScore,
          history: info.history
        };
      });

      if (students.length === 0) throw new Error("No student records found. Check mapping.");

      onComplete({
        students,
        subjects: allSubjects,
        classes: [...new Set(students.map(s => s.class))],
        schoolStats: {
          average: students.reduce((acc, s) => acc + s.totalScore, 0) / students.length,
          max: Math.max(...students.map(s => s.totalScore)),
          min: Math.min(...students.map(s => s.totalScore)),
          subjectStats: {},
          distribution: []
        }
      });
    } catch (err: any) {
      console.error(err);
      alert(`Error processing records: ${err.message || 'Check your mapping and file format.'}`);
    } finally {
      setLoading(false);
    }
  };

  const availableSubjectColumns = useMemo(() => {
    return headers.filter(h => h !== mapping.name && h !== mapping.class);
  }, [headers, mapping.name, mapping.class]);

  const isMappingValid = mapping.name && mapping.class && Object.keys(mapping.subjects).length > 0;

  return (
    <div className="bg-white rounded-3xl border border-gray-100 shadow-2xl overflow-hidden animate-in zoom-in-95 duration-300">
      <div className="flex border-b border-gray-50">
        {[1, 2, 3].map(i => (
          <div key={i} className={`flex-1 py-4 text-center text-[10px] font-black uppercase tracking-widest transition-colors ${step >= i ? 'text-blue-600 bg-blue-50/50' : 'text-gray-300'}`}>
            Step {i}: {i === 1 ? 'Upload' : i === 2 ? 'Config' : 'Mapping'}
          </div>
        ))}
      </div>

      <div className="p-8 min-h-[400px]">
        {step === 1 && (
          <div className="space-y-6 animate-in slide-in-from-bottom-4">
            <div className="border-2 border-dashed border-gray-200 rounded-2xl p-10 text-center relative group hover:border-blue-400 transition-all">
              <input type="file" multiple={structure === 'multi-file-single'} onChange={handleFileChange} className="absolute inset-0 opacity-0 cursor-pointer" />
              <Upload className="w-12 h-12 text-blue-600 mx-auto mb-4 group-hover:scale-110 transition-transform" />
              <h3 className="text-lg font-bold text-gray-800">Drop your Excel files here</h3>
              <p className="text-sm text-gray-400">Supported formats: .xlsx, .xls</p>
            </div>
            {files.length > 0 && (
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                {files.map((f, i) => (
                  <div key={i} className="bg-gray-50 p-3 rounded-xl flex items-center justify-between border border-gray-100">
                    <div className="flex items-center gap-2">
                      <FileText className="w-4 h-4 text-gray-400" />
                      <span className="text-xs font-bold text-gray-700 truncate max-w-[150px]">{f.name}</span>
                    </div>
                    <button onClick={() => setFiles(prev => prev.filter((_, idx) => idx !== i))} className="p-1 hover:bg-gray-200 rounded-lg text-gray-400">
                      <X className="w-4 h-4" />
                    </button>
                  </div>
                ))}
              </div>
            )}
          </div>
        )}

        {step === 2 && (
          <div className="space-y-8 animate-in slide-in-from-right-4 overflow-y-auto max-h-[500px]">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
              <div className="space-y-6">
                <div className="space-y-3">
                  <label className="text-xs font-black text-gray-400 uppercase tracking-widest flex items-center gap-2">
                    <LayoutGrid className="w-3 h-3" /> Data Mode
                  </label>
                  <div className="grid grid-cols-1 gap-2">
                    <button onClick={() => setMode('complete')} className={`p-4 rounded-xl border text-left transition-all ${mode === 'complete' ? 'border-blue-600 bg-blue-50' : 'border-gray-100 hover:border-blue-200'}`}>
                      <div className="flex items-center justify-between mb-1">
                        <span className="font-bold text-gray-800 text-sm">Whole School (Cohort)</span>
                        {mode === 'complete' && <CheckCircle2 className="w-4 h-4 text-blue-600" />}
                      </div>
                      <p className="text-[10px] text-gray-500">File contains all student records for full ranking computation.</p>
                    </button>
                    <button onClick={() => setMode('incomplete')} className={`p-4 rounded-xl border text-left transition-all ${mode === 'incomplete' ? 'border-blue-600 bg-blue-50' : 'border-gray-100 hover:border-blue-200'}`}>
                      <div className="flex items-center justify-between mb-1">
                        <span className="font-bold text-gray-800 text-sm">Partial Sample / Group</span>
                        {mode === 'incomplete' && <CheckCircle2 className="w-4 h-4 text-blue-600" />}
                      </div>
                      <p className="text-[10px] text-gray-500">File only contains specific groups. Ranks might be skewed.</p>
                    </button>
                  </div>
                </div>

                <div className="space-y-3">
                  <label className="text-xs font-black text-gray-400 uppercase tracking-widest flex items-center gap-2">
                    <ListFilter className="w-3 h-3" /> Table Layout
                  </label>
                  <div className="grid grid-cols-1 gap-2">
                    <button onClick={() => setStructure('multi-file-single')} className={`p-4 rounded-xl border text-left transition-all ${structure === 'multi-file-single' ? 'border-orange-600 bg-orange-50' : 'border-gray-100 hover:border-orange-200'}`}>
                      <div className="flex items-center justify-between mb-1">
                        <span className="font-bold text-gray-800 text-sm">One Exam Per File</span>
                        {structure === 'multi-file-single' && <CheckCircle2 className="w-4 h-4 text-orange-600" />}
                      </div>
                      <p className="text-[10px] text-gray-500">Traditional format. Select multiple files to build a timeline.</p>
                    </button>
                    <button onClick={() => setStructure('single-file-multi')} className={`p-4 rounded-xl border text-left transition-all ${structure === 'single-file-multi' ? 'border-orange-600 bg-orange-50' : 'border-gray-100 hover:border-orange-200'}`}>
                      <div className="flex items-center justify-between mb-1">
                        <span className="font-bold text-gray-800 text-sm">Multi-Exam Summary Table</span>
                        {structure === 'single-file-multi' && <CheckCircle2 className="w-4 h-4 text-orange-600" />}
                      </div>
                      <p className="text-[10px] text-gray-500">Single file with grouped student records (e.g. 5 rows for 1 student).</p>
                    </button>
                  </div>
                </div>
              </div>

              <div className="space-y-6">
                <div className="space-y-3">
                  <label className="text-xs font-black text-gray-400 uppercase tracking-widest flex items-center gap-2">
                    <Settings2 className="w-3 h-3" /> Ranking Authority
                  </label>
                  <div className="grid grid-cols-1 gap-2">
                    <button onClick={() => setRankSource('recalculate')} className={`p-4 rounded-xl border text-left transition-all ${rankSource === 'recalculate' ? 'border-indigo-600 bg-indigo-50' : 'border-gray-100 hover:border-indigo-200'}`}>
                      <div className="flex items-center justify-between mb-1">
                        <span className="font-bold text-gray-800 text-sm">System Calculation</span>
                        {rankSource === 'recalculate' && <CheckCircle2 className="w-4 h-4 text-indigo-600" />}
                      </div>
                      <p className="text-[10px] text-gray-500">Derive all rankings automatically based on total scores.</p>
                    </button>
                    <button onClick={() => setRankSource('imported')} className={`p-4 rounded-xl border text-left transition-all ${rankSource === 'imported' ? 'border-indigo-600 bg-indigo-50' : 'border-gray-100 hover:border-indigo-200'}`}>
                      <div className="flex items-center justify-between mb-1">
                        <span className="font-bold text-gray-800 text-sm">Imported Metadata</span>
                        {rankSource === 'imported' && <CheckCircle2 className="w-4 h-4 text-indigo-600" />}
                      </div>
                      <p className="text-[10px] text-gray-500">Use pre-existing ranking columns from your Excel file.</p>
                    </button>
                  </div>
                </div>
                {structure === 'single-file-multi' && (
                  <div className="space-y-2 p-5 bg-gray-50 rounded-2xl border border-gray-100 animate-in fade-in slide-in-from-top-2">
                    <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Define Exam Sequence (Comma separated)</label>
                    <input type="text" value={periodNamesInput} onChange={(e) => setPeriodNamesInput(e.target.value)} placeholder="e.g. Sep Monthly, Mid-term, Dec Monthly..." className="w-full bg-white border border-gray-200 rounded-lg px-3 py-2 text-xs outline-none focus:ring-2 focus:ring-blue-500" />
                    <p className="text-[8px] text-gray-400 leading-tight mt-1">Order should match the sequence of appearances for each student in the file.</p>
                  </div>
                )}
              </div>
            </div>
          </div>
        )}

        {step === 3 && (
          <div className="space-y-6 animate-in slide-in-from-right-4 max-h-[500px] overflow-y-auto pr-2 custom-scrollbar">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
              <div className="space-y-4">
                <h4 className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Identity Columns</h4>
                <div className="space-y-3">
                  <div className="flex items-center justify-between gap-4">
                    <span className="text-sm font-bold text-gray-700 whitespace-nowrap">Student Name</span>
                    <select value={mapping.name} onChange={(e) => setMapping({...mapping, name: e.target.value})} className="w-full bg-gray-50 border border-gray-200 rounded-lg px-3 py-2 text-xs outline-none focus:ring-2 focus:ring-blue-500">
                      <option value="">-- Choose Column --</option>
                      {headers.map(h => <option key={h} value={h}>{h}</option>)}
                    </select>
                  </div>
                  <div className="flex items-center justify-between gap-4">
                    <span className="text-sm font-bold text-gray-700 whitespace-nowrap">Class Group</span>
                    <select value={mapping.class} onChange={(e) => setMapping({...mapping, class: e.target.value})} className="w-full bg-gray-50 border border-gray-200 rounded-lg px-3 py-2 text-xs outline-none focus:ring-2 focus:ring-blue-500">
                      <option value="">-- Choose Column --</option>
                      {headers.map(h => <option key={h} value={h}>{h}</option>)}
                    </select>
                  </div>
                </div>
              </div>
              <div className="space-y-4">
                <h4 className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Global Metrices</h4>
                <div className="flex items-center justify-between gap-4">
                  <span className="text-sm font-bold text-gray-700 whitespace-nowrap">Total Rank</span>
                  <select disabled={rankSource === 'recalculate'} value={mapping.totalRank} onChange={(e) => setMapping({...mapping, totalRank: e.target.value})} className="w-full bg-gray-50 border border-gray-200 rounded-lg px-3 py-2 text-xs outline-none focus:ring-2 focus:ring-blue-500 disabled:opacity-50">
                    <option value="">(Not Specified)</option>
                    {headers.map(h => <option key={h} value={h}>{h}</option>)}
                  </select>
                </div>
              </div>
            </div>

            <div className="space-y-4 pt-6">
              <h4 className="text-[10px] font-black text-gray-400 uppercase tracking-widest flex items-center justify-between">
                <span>Subject Mapping</span>
                <span className="text-blue-600 normal-case font-bold">{Object.keys(mapping.subjects).length} Selected</span>
              </h4>
              <div className="grid grid-cols-1 gap-2">
                {availableSubjectColumns.length === 0 && <p className="text-center py-12 text-gray-400 text-sm italic border-2 border-dashed rounded-2xl">First specify Name and Class columns to reveal remaining fields.</p>}
                {availableSubjectColumns.map(h => (
                  <div key={h} className={`bg-gray-50 p-4 rounded-xl flex items-center justify-between border transition-all ${mapping.subjects[h] ? 'border-blue-200 bg-blue-50/50' : 'border-gray-100 hover:border-blue-300'}`}>
                    <div className="flex items-center gap-3">
                      <Table className={`w-4 h-4 ${mapping.subjects[h] ? 'text-blue-500' : 'text-gray-400'}`} />
                      <span className={`text-sm font-bold ${mapping.subjects[h] ? 'text-blue-900' : 'text-gray-700'}`}>{h}</span>
                    </div>
                    <div className="flex items-center gap-4">
                      {rankSource === 'imported' && mapping.subjects[h] && (
                        <div className="flex items-center gap-2 bg-white px-3 py-1.5 rounded-lg border border-gray-100 shadow-sm animate-in fade-in slide-in-from-right-1">
                          <span className="text-[10px] font-bold text-gray-400 uppercase">Rank Col:</span>
                          <select 
                            value={mapping.subjectRanks[h] || ''} 
                            onChange={(e) => setMapping({...mapping, subjectRanks: { ...mapping.subjectRanks, [h]: e.target.value }})}
                            className="bg-transparent text-[10px] outline-none font-bold text-indigo-600"
                          >
                            <option value="">(None)</option>
                            {headers.map(head => <option key={head} value={head}>{head}</option>)}
                          </select>
                        </div>
                      )}
                      <input 
                        type="checkbox" 
                        checked={!!mapping.subjects[h]} 
                        onChange={(e) => {
                          const newSubs = { ...mapping.subjects };
                          if (e.target.checked) newSubs[h] = h;
                          else delete newSubs[h];
                          setMapping({...mapping, subjects: newSubs});
                        }}
                        className="w-5 h-5 rounded text-blue-600 cursor-pointer border-gray-300 focus:ring-blue-500"
                      />
                    </div>
                  </div>
                ))}
              </div>
            </div>
          </div>
        )}
      </div>

      <div className="bg-gray-50 p-8 flex justify-between items-center border-t border-gray-100">
        <button onClick={onCancel} className="text-gray-500 font-bold hover:text-gray-800 transition-colors">Discard & Close</button>
        <div className="flex gap-4">
          {step > 1 && (
            <button onClick={() => setStep(step - 1)} className="px-8 py-3 rounded-xl border border-gray-200 font-bold text-gray-600 hover:bg-gray-100 transition-all flex items-center gap-2">
              <ArrowLeft className="w-4 h-4" /> Back
            </button>
          )}
          {step < 3 ? (
            <button disabled={files.length === 0} onClick={() => setStep(step + 1)} className="px-10 py-3 rounded-xl bg-blue-600 text-white font-bold disabled:opacity-50 hover:bg-blue-700 shadow-lg shadow-blue-100 transition-all flex items-center gap-2">
              Continue <ArrowRight className="w-4 h-4" />
            </button>
          ) : (
            <button disabled={!isMappingValid || loading} onClick={handleFinalImport} className="px-12 py-3 rounded-xl bg-green-600 text-white font-bold disabled:opacity-50 hover:bg-green-700 shadow-lg shadow-green-100 transition-all flex items-center gap-2">
              {loading ? 'Processing Data...' : 'Confirm & Build Dashboard'} <CheckCircle2 className="w-4 h-4" />
            </button>
          )}
        </div>
      </div>
    </div>
  );
};

export default ImportWizard;

export interface ScoreSnapshot {
  period: string; // e.g., "Term 1"
  totalScore: number;
  averageScore: number;
  scores: Record<string, number>;
  ranks?: Record<string, number>; // Imported ranks
  schoolRank?: number; // Imported school total rank
  status?: string; // Imported admission status (e.g., "特控", "一本", "本科")
  isComplete?: boolean; // Data completeness flag
}

export interface StudentRecord {
  id: string;
  name: string;
  class: string;
  scores: Record<string, number>;
  totalScore: number;
  averageScore: number;
  history: ScoreSnapshot[]; 
}

export interface ExamEntity {
  id: string;
  name: string;
  weight: number;
  isComplete: boolean;
  fileCount: number;
}

export interface AnalysisState {
  students: StudentRecord[];
  subjects: string[];
  classes: string[];
  schoolStats: {
    average: number;
    max: number;
    min: number;
    subjectStats: Record<string, { average: number; max: number; min: number }>;
    distribution: { name: string; value: number; color: string }[];
  };
}

export type ImportMode = 'complete' | 'incomplete';
export type DataStructure = 'multi-file-single' | 'single-file-multi';
export type RankSource = 'recalculate' | 'imported';

export interface ColumnMapping {
  name: string;
  class: string;
  subjects: Record<string, string>;
  subjectRanks: Record<string, string>;
  totalRank?: string;
  status?: string;
}

// Fixed the global augmentation by using uppercase Window interface.
declare global {
  interface Window {
    XLSX: any;
  }
}

import React, { useState, useMemo } from 'react';
import { Upload, X, ArrowRight, ArrowLeft, Table, CheckCircle2, AlertCircle, FileText, LayoutGrid, ListFilter, Settings2, UserCheck } from 'lucide-react';
import { AnalysisState, ImportMode, DataStructure, RankSource, ColumnMapping, StudentRecord, ScoreSnapshot } from '../types';

interface ImportWizardProps {
  onComplete: (data: AnalysisState) => void;
  onCancel: () => void;
  currentData: AnalysisState | null;
}

const ImportWizard: React.FC<ImportWizardProps> = ({ onComplete, onCancel, currentData }) => {
  const [step, setStep] = useState(1);
  const [files, setFiles] = useState<File[]>([]);
  const [mode, setMode] = useState<ImportMode>('complete');
  const [structure, setStructure] = useState<DataStructure>('multi-file-single');
  const [rankSource, setRankSource] = useState<RankSource>('recalculate');
  const [periodNamesInput, setPeriodNamesInput] = useState<string>('');

  const [headers, setHeaders] = useState<string[]>([]);
  const [mapping, setMapping] = useState<ColumnMapping>({
    name: '',
    class: '',
    subjects: {},
    subjectRanks: {}
  });

  const [loading, setLoading] = useState(false);

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (!e.target.files || e.target.files.length === 0) return;
    const newFiles = Array.from(e.target.files) as File[];
    setFiles(prev => [...prev, ...newFiles]);

    const reader = new FileReader();
    reader.onload = (evt) => {
      const bstr = evt.target?.result;
      const wb = (window as any).XLSX.read(bstr, { type: 'binary' });
      const ws = wb.Sheets[wb.SheetNames[0]];

      const rows = (window as any).XLSX.utils.sheet_to_json(ws, { header: 1 });
      if (rows.length > 0) {
        const firstRow = rows.find((r: any[]) => r && r.length > 0) as any[];
        if (!firstRow) return;

        const foundHeaders = firstRow.map(h => String(h || '').trim()).filter(h => h.length > 0);
        setHeaders(foundHeaders);

        const autoMapping: ColumnMapping = {
          name: '',
          class: '',
          subjects: {},
          subjectRanks: {}
        };

        // Improved Chinese and English header detection
        foundHeaders.forEach(h => {
          const lower = h.toLowerCase();
          if (!autoMapping.name && (lower === '姓名' || lower === 'name' || lower.includes('学生姓名') || lower === '学生')) {
            autoMapping.name = h;
          } else if (!autoMapping.class && (lower === '班级' || lower === '班' || lower === 'class' || lower.includes('班级名称') || lower === '班别')) {
            autoMapping.class = h;
          }
        });

        foundHeaders.forEach(h => {
          if (h === autoMapping.name || h === autoMapping.class) return;
          const lower = h.toLowerCase();
          const isRankCol = lower.includes('名') || lower.includes('次') || lower.includes('rank') || lower === '排名';
          const isIdCol = lower.includes('号') || lower.includes('学') || lower.includes('id') || lower === '学籍';
          const isStatusCol = lower.includes('上线') || lower.includes('状态') || lower === '等级' || lower === '录取';

          if (!isRankCol && !isIdCol && !isStatusCol) {
            autoMapping.subjects[h] = h;
          }

          // Auto-pick rank column if source is imported
          if (!autoMapping.totalRank && (lower === '级名' || lower === '年级排名' || lower === '全校名次' || lower === '总分名次' || lower === 'total rank')) {
            autoMapping.totalRank = h;
          }

          // Auto-pick status column
          if (!autoMapping.status && (lower === '上线' || lower === '上线情况' || lower === '录取状态' || lower === 'admission' || lower === 'status')) {
            autoMapping.status = h;
          }
        });

        setMapping(autoMapping);
      }
    };
    reader.readAsBinaryString(newFiles[0]);
  };

  const handleFinalImport = async () => {
    setLoading(true);
    try {
      const allSubjects = Object.keys(mapping.subjects);
      const studentMap = new Map<string, { class: string; history: ScoreSnapshot[] }>();

      // Load existing state to allow incremental updates
      if (currentData) {
        currentData.students.forEach(s => {
          studentMap.set(s.name, { class: s.class, history: [...s.history] });
        });
      }

      const getFileContent = (file: File) => new Promise<any[]>((resolve) => {
        const reader = new FileReader();
        reader.onload = (e) => {
          const wb = (window as any).XLSX.read(e.target?.result, { type: 'binary' });
          resolve((window as any).XLSX.utils.sheet_to_json(wb.Sheets[wb.SheetNames[0]], { defval: null }));
        };
        reader.readAsBinaryString(file);
      });

      const createSnapshot = (row: any, period: string, subs: string[]): ScoreSnapshot => {
        const scores: Record<string, number> = {};
        const ranks: Record<string, number> = {};
        let total = 0;

        subs.forEach(sub => {
          const val = row[mapping.subjects[sub]];
          const score = typeof val === 'number' ? val : parseFloat(String(val || '0')) || 0;
          scores[sub] = score;
          total += score;

          if (rankSource === 'imported' && mapping.subjectRanks[sub]) {
            const rankVal = row[mapping.subjectRanks[sub]];
            ranks[sub] = typeof rankVal === 'number' ? rankVal : parseInt(String(rankVal || '0')) || 0;
          }
        });

        return {
          period,
          scores,
          ranks: rankSource === 'imported' ? ranks : undefined,
          totalScore: parseFloat(total.toFixed(2)),
          averageScore: parseFloat((total / (subs.length || 1)).toFixed(2)),
          schoolRank: rankSource === 'imported' && mapping.totalRank ? parseInt(String(row[mapping.totalRank] || '0')) : undefined,
          status: rankSource === 'imported' && mapping.status ? String(row[mapping.status] || '').trim() : undefined,
          isComplete: mode === 'complete'
        };
      };

      if (structure === 'multi-file-single') {
        for (const file of files) {
          const periodName = file.name.replace(/\.[^/.]+$/, "").replace(/[_-]/g, " ");
          const content = await getFileContent(file);

          content.forEach((row: any) => {
            const name = String(row[mapping.name] || '').trim();
            if (!name || name === 'undefined' || name === mapping.name || name.toLowerCase() === 'name') return;

            const snapshot = createSnapshot(row, periodName, allSubjects);
            if (!studentMap.has(name)) {
              studentMap.set(name, { class: String(row[mapping.class] || '').trim(), history: [] });
            }
            const info = studentMap.get(name)!;
            const existingIdx = info.history.findIndex(h => h.period === periodName);
            if (existingIdx >= 0) info.history[existingIdx] = snapshot;
            else info.history.push(snapshot);
          });
        }
      } else {
        // Single File Summary Table - Multiple Rows per student
        const content = await getFileContent(files[0]);
        const periods = periodNamesInput.split(',').map(s => s.trim()).filter(Boolean);

        // Group rows by student name
        const studentRows = new Map<string, { class: string, rows: any[] }>();
        content.forEach(row => {
          const name = String(row[mapping.name] || '').trim();
          if (!name || name === 'undefined' || name === mapping.name || name.toLowerCase() === 'name') return;

          if (!studentRows.has(name)) {
            studentRows.set(name, { class: String(row[mapping.class] || '').trim(), rows: [] });
          }
          studentRows.get(name)!.rows.push(row);
        });

        // Use period names from input or default numbering
        const maxExams = Array.from(studentRows.values()).reduce((max, s) => Math.max(max, s.rows.length), 0);
        const finalPeriodNames = Array.from({ length: maxExams }, (_, i) => periods[i] || `Exam ${i + 1}`);

        studentRows.forEach((data, name) => {
          if (!studentMap.has(name)) {
            studentMap.set(name, { class: data.class, history: [] });
          }
          const info = studentMap.get(name)!;

          data.rows.forEach((row, idx) => {
            const periodName = finalPeriodNames[idx];
            const snapshot = createSnapshot(row, periodName, allSubjects);

            // Deduplicate period records
            const existingIdx = info.history.findIndex(h => h.period === periodName);
            if (existingIdx >= 0) {
              info.history[existingIdx] = snapshot;
            } else {
              info.history.push(snapshot);
            }
          });
        });
      }

      // Final transformation to StudentRecord array
      const students: StudentRecord[] = Array.from(studentMap.entries()).map(([name, info], index) => {
        // Sort history by the order they were imported or by period names
        const latest = info.history[info.history.length - 1];
        return {
          id: `s-${index}`,
          name,
          class: info.class,
          scores: latest.scores,
          totalScore: latest.totalScore,
          averageScore: latest.averageScore,
          history: info.history
        };
      });

      if (students.length === 0) throw new Error("No student records found. Check mapping.");

      onComplete({
        students,
        subjects: allSubjects,
        classes: [...new Set(students.map(s => s.class))],
        schoolStats: {
          average: students.reduce((acc, s) => acc + s.totalScore, 0) / students.length,
          max: Math.max(...students.map(s => s.totalScore)),
          min: Math.min(...students.map(s => s.totalScore)),
          subjectStats: {},
          distribution: []
        }
      });
    } catch (err: any) {
      console.error(err);
      alert(`Error processing records: ${err.message || 'Check your mapping and file format.'}`);
    } finally {
      setLoading(false);
    }
  };

  const availableSubjectColumns = useMemo(() => {
    return headers.filter(h => h !== mapping.name && h !== mapping.class);
  }, [headers, mapping.name, mapping.class]);

  const isMappingValid = mapping.name && mapping.class && Object.keys(mapping.subjects).length > 0;

  return (
    <div className="bg-white rounded-3xl border border-gray-100 shadow-2xl overflow-hidden animate-in zoom-in-95 duration-300">
      <div className="flex border-b border-gray-50">
        {[1, 2, 3].map(i => (
          <div key={i} className={`flex-1 py-4 text-center text-[10px] font-black uppercase tracking-widest transition-colors ${step >= i ? 'text-blue-600 bg-blue-50/50' : 'text-gray-300'}`}>
            Step {i}: {i === 1 ? 'Upload' : i === 2 ? 'Config' : 'Mapping'}
          </div>
        ))}
      </div>

      <div className="p-8 min-h-[400px]">
        {step === 1 && (
          <div className="space-y-6 animate-in slide-in-from-bottom-4">
            <div className="border-2 border-dashed border-gray-200 rounded-2xl p-10 text-center relative group hover:border-blue-400 transition-all">
              <input type="file" multiple={structure === 'multi-file-single'} onChange={handleFileChange} className="absolute inset-0 opacity-0 cursor-pointer" />
              <Upload className="w-12 h-12 text-blue-600 mx-auto mb-4 group-hover:scale-110 transition-transform" />
              <h3 className="text-lg font-bold text-gray-800">Drop your Excel files here</h3>
              <p className="text-sm text-gray-400">Supported formats: .xlsx, .xls</p>
            </div>
            {files.length > 0 && (
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                {files.map((f, i) => (
                  <div key={i} className="bg-gray-50 p-3 rounded-xl flex items-center justify-between border border-gray-100">
                    <div className="flex items-center gap-2">
                      <FileText className="w-4 h-4 text-gray-400" />
                      <span className="text-xs font-bold text-gray-700 truncate max-w-[150px]">{f.name}</span>
                    </div>
                    <button onClick={() => setFiles(prev => prev.filter((_, idx) => idx !== i))} className="p-1 hover:bg-gray-200 rounded-lg text-gray-400">
                      <X className="w-4 h-4" />
                    </button>
                  </div>
                ))}
              </div>
            )}
          </div>
        )}

        {step === 2 && (
          <div className="space-y-8 animate-in slide-in-from-right-4 overflow-y-auto max-h-[500px]">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
              <div className="space-y-6">
                <div className="space-y-3">
                  <label className="text-xs font-black text-gray-400 uppercase tracking-widest flex items-center gap-2">
                    <LayoutGrid className="w-3 h-3" /> Data Mode
                  </label>
                  <div className="grid grid-cols-1 gap-2">
                    <button onClick={() => setMode('complete')} className={`p-4 rounded-xl border text-left transition-all ${mode === 'complete' ? 'border-blue-600 bg-blue-50' : 'border-gray-100 hover:border-blue-200'}`}>
                      <div className="flex items-center justify-between mb-1">
                        <span className="font-bold text-gray-800 text-sm">Whole School (Cohort)</span>
                        {mode === 'complete' && <CheckCircle2 className="w-4 h-4 text-blue-600" />}
                      </div>
                      <p className="text-[10px] text-gray-500">File contains all student records for full ranking computation.</p>
                    </button>
                    <button onClick={() => setMode('incomplete')} className={`p-4 rounded-xl border text-left transition-all ${mode === 'incomplete' ? 'border-blue-600 bg-blue-50' : 'border-gray-100 hover:border-blue-200'}`}>
                      <div className="flex items-center justify-between mb-1">
                        <span className="font-bold text-gray-800 text-sm">Partial Sample / Group</span>
                        {mode === 'incomplete' && <CheckCircle2 className="w-4 h-4 text-blue-600" />}
                      </div>
                      <p className="text-[10px] text-gray-500">File only contains specific groups. Ranks might be skewed.</p>
                    </button>
                  </div>
                </div>

                <div className="space-y-3">
                  <label className="text-xs font-black text-gray-400 uppercase tracking-widest flex items-center gap-2">
                    <ListFilter className="w-3 h-3" /> Table Layout
                  </label>
                  <div className="grid grid-cols-1 gap-2">
                    <button onClick={() => setStructure('multi-file-single')} className={`p-4 rounded-xl border text-left transition-all ${structure === 'multi-file-single' ? 'border-orange-600 bg-orange-50' : 'border-gray-100 hover:border-orange-200'}`}>
                      <div className="flex items-center justify-between mb-1">
                        <span className="font-bold text-gray-800 text-sm">One Exam Per File</span>
                        {structure === 'multi-file-single' && <CheckCircle2 className="w-4 h-4 text-orange-600" />}
                      </div>
                      <p className="text-[10px] text-gray-500">Traditional format. Select multiple files to build a timeline.</p>
                    </button>
                    <button onClick={() => setStructure('single-file-multi')} className={`p-4 rounded-xl border text-left transition-all ${structure === 'single-file-multi' ? 'border-orange-600 bg-orange-50' : 'border-gray-100 hover:border-orange-200'}`}>
                      <div className="flex items-center justify-between mb-1">
                        <span className="font-bold text-gray-800 text-sm">Multi-Exam Summary Table</span>
                        {structure === 'single-file-multi' && <CheckCircle2 className="w-4 h-4 text-orange-600" />}
                      </div>
                      <p className="text-[10px] text-gray-500">Single file with grouped student records (e.g. 5 rows for 1 student).</p>
                    </button>
                  </div>
                </div>
              </div>

              <div className="space-y-6">
                <div className="space-y-3">
                  <label className="text-xs font-black text-gray-400 uppercase tracking-widest flex items-center gap-2">
                    <Settings2 className="w-3 h-3" /> Ranking Authority
                  </label>
                  <div className="grid grid-cols-1 gap-2">
                    <button onClick={() => setRankSource('recalculate')} className={`p-4 rounded-xl border text-left transition-all ${rankSource === 'recalculate' ? 'border-indigo-600 bg-indigo-50' : 'border-gray-100 hover:border-indigo-200'}`}>
                      <div className="flex items-center justify-between mb-1">
                        <span className="font-bold text-gray-800 text-sm">System Calculation</span>
                        {rankSource === 'recalculate' && <CheckCircle2 className="w-4 h-4 text-indigo-600" />}
                      </div>
                      <p className="text-[10px] text-gray-500">Derive all rankings automatically based on total scores.</p>
                    </button>
                    <button onClick={() => setRankSource('imported')} className={`p-4 rounded-xl border text-left transition-all ${rankSource === 'imported' ? 'border-indigo-600 bg-indigo-50' : 'border-gray-100 hover:border-indigo-200'}`}>
                      <div className="flex items-center justify-between mb-1">
                        <span className="font-bold text-gray-800 text-sm">Imported Metadata</span>
                        {rankSource === 'imported' && <CheckCircle2 className="w-4 h-4 text-indigo-600" />}
                      </div>
                      <p className="text-[10px] text-gray-500">Use pre-existing ranking columns from your Excel file.</p>
                    </button>
                  </div>
                </div>
                {structure === 'single-file-multi' && (
                  <div className="space-y-2 p-5 bg-gray-50 rounded-2xl border border-gray-100 animate-in fade-in slide-in-from-top-2">
                    <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Define Exam Sequence (Comma separated)</label>
                    <input type="text" value={periodNamesInput} onChange={(e) => setPeriodNamesInput(e.target.value)} placeholder="e.g. Sep Monthly, Mid-term, Dec Monthly..." className="w-full bg-white border border-gray-200 rounded-lg px-3 py-2 text-xs outline-none focus:ring-2 focus:ring-blue-500" />
                    <p className="text-[8px] text-gray-400 leading-tight mt-1">Order should match the sequence of appearances for each student in the file.</p>
                  </div>
                )}
              </div>
            </div>
          </div>
        )}

        {step === 3 && (
          <div className="space-y-6 animate-in slide-in-from-right-4 max-h-[500px] overflow-y-auto pr-2 custom-scrollbar">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
              <div className="space-y-4">
                <h4 className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Identity Columns</h4>
                <div className="space-y-3">
                  <div className="flex items-center justify-between gap-4">
                    <span className="text-sm font-bold text-gray-700 whitespace-nowrap">Student Name</span>
                    <select value={mapping.name} onChange={(e) => setMapping({...mapping, name: e.target.value})} className="w-full bg-gray-50 border border-gray-200 rounded-lg px-3 py-2 text-xs outline-none focus:ring-2 focus:ring-blue-500">
                      <option value="">-- Choose Column --</option>
                      {headers.map(h => <option key={h} value={h}>{h}</option>)}
                    </select>
                  </div>
                  <div className="flex items-center justify-between gap-4">
                    <span className="text-sm font-bold text-gray-700 whitespace-nowrap">Class Group</span>
                    <select value={mapping.class} onChange={(e) => setMapping({...mapping, class: e.target.value})} className="w-full bg-gray-50 border border-gray-200 rounded-lg px-3 py-2 text-xs outline-none focus:ring-2 focus:ring-blue-500">
                      <option value="">-- Choose Column --</option>
                      {headers.map(h => <option key={h} value={h}>{h}</option>)}
                    </select>
                  </div>
                </div>
              </div>
              <div className="space-y-4">
                <h4 className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Global Metrices</h4>
                <div className="space-y-3">
                  <div className="flex items-center justify-between gap-4">
                    <span className="text-sm font-bold text-gray-700 whitespace-nowrap">Total Rank</span>
                    <select disabled={rankSource === 'recalculate'} value={mapping.totalRank} onChange={(e) => setMapping({...mapping, totalRank: e.target.value})} className="w-full bg-gray-50 border border-gray-200 rounded-lg px-3 py-2 text-xs outline-none focus:ring-2 focus:ring-blue-500 disabled:opacity-50">
                      <option value="">(Not Specified)</option>
                      {headers.map(h => <option key={h} value={h}>{h}</option>)}
                    </select>
                  </div>
                  <div className="flex items-center justify-between gap-4">
                    <span className="text-sm font-bold text-gray-700 whitespace-nowrap flex items-center gap-2">
                      <UserCheck className="w-4 h-4 text-blue-500" /> Admission Status
                    </span>
                    <select disabled={rankSource === 'recalculate'} value={mapping.status} onChange={(e) => setMapping({...mapping, status: e.target.value})} className="w-full bg-gray-50 border border-gray-200 rounded-lg px-3 py-2 text-xs outline-none focus:ring-2 focus:ring-blue-500 disabled:opacity-50">
                      <option value="">(Not Specified)</option>
                      {headers.map(h => <option key={h} value={h}>{h}</option>)}
                    </select>
                  </div>
                </div>
              </div>
            </div>

            <div className="space-y-4 pt-6">
              <h4 className="text-[10px] font-black text-gray-400 uppercase tracking-widest flex items-center justify-between">
                <span>Subject Mapping</span>
                <span className="text-blue-600 normal-case font-bold">{Object.keys(mapping.subjects).length} Selected</span>
              </h4>
              <div className="grid grid-cols-1 gap-2">
                {availableSubjectColumns.length === 0 && <p className="text-center py-12 text-gray-400 text-sm italic border-2 border-dashed rounded-2xl">First specify Name and Class columns to reveal remaining fields.</p>}
                {availableSubjectColumns.map(h => (
                  <div key={h} className={`bg-gray-50 p-4 rounded-xl flex items-center justify-between border transition-all ${mapping.subjects[h] ? 'border-blue-200 bg-blue-50/50' : 'border-gray-100 hover:border-blue-300'}`}>
                    <div className="flex items-center gap-3">
                      <Table className={`w-4 h-4 ${mapping.subjects[h] ? 'text-blue-500' : 'text-gray-400'}`} />
                      <span className={`text-sm font-bold ${mapping.subjects[h] ? 'text-blue-900' : 'text-gray-700'}`}>{h}</span>
                    </div>
                    <div className="flex items-center gap-4">
                      {rankSource === 'imported' && mapping.subjects[h] && (
                        <div className="flex items-center gap-2 bg-white px-3 py-1.5 rounded-lg border border-gray-100 shadow-sm animate-in fade-in slide-in-from-right-1">
                          <span className="text-[10px] font-bold text-gray-400 uppercase">Rank Col:</span>
                          <select 
                            value={mapping.subjectRanks[h] || ''} 
                            onChange={(e) => setMapping({...mapping, subjectRanks: { ...mapping.subjectRanks, [h]: e.target.value }})}
                            className="bg-transparent text-[10px] outline-none font-bold text-indigo-600"
                          >
                            <option value="">(None)</option>
                            {headers.map(head => <option key={head} value={head}>{head}</option>)}
                          </select>
                        </div>
                      )}
                      <input 
                        type="checkbox" 
                        checked={!!mapping.subjects[h]} 
                        onChange={(e) => {
                          const newSubs = { ...mapping.subjects };
                          if (e.target.checked) newSubs[h] = h;
                          else delete newSubs[h];
                          setMapping({...mapping, subjects: newSubs});
                        }}
                        className="w-5 h-5 rounded text-blue-600 cursor-pointer border-gray-300 focus:ring-blue-500"
                      />
                    </div>
                  </div>
                ))}
              </div>
            </div>
          </div>
        )}
      </div>

      <div className="bg-gray-50 p-8 flex justify-between items-center border-t border-gray-100">
        <button onClick={onCancel} className="text-gray-500 font-bold hover:text-gray-800 transition-colors">Discard & Close</button>
        <div className="flex gap-4">
          {step > 1 && (
            <button onClick={() => setStep(step - 1)} className="px-8 py-3 rounded-xl border border-gray-200 font-bold text-gray-600 hover:bg-gray-100 transition-all flex items-center gap-2">
              <ArrowLeft className="w-4 h-4" /> Back
            </button>
          )}
          {step < 3 ? (
            <button disabled={files.length === 0} onClick={() => setStep(step + 1)} className="px-10 py-3 rounded-xl bg-blue-600 text-white font-bold disabled:opacity-50 hover:bg-blue-700 shadow-lg shadow-blue-100 transition-all flex items-center gap-2">
              Continue <ArrowRight className="w-4 h-4" />
            </button>
          ) : (
            <button disabled={!isMappingValid || loading} onClick={handleFinalImport} className="px-12 py-3 rounded-xl bg-green-600 text-white font-bold disabled:opacity-50 hover:bg-green-700 shadow-lg shadow-green-100 transition-all flex items-center gap-2">
              {loading ? 'Processing Data...' : 'Confirm & Build Dashboard'} <CheckCircle2 className="w-4 h-4" />
            </button>
          )}
        </div>
      </div>
    </div>
  );
};

export default ImportWizard;

import { StudentRecord, ScoreSnapshot } from '../types';

/**
 * 统一计算全周期总分名次映射
 * 返回格式: { [PeriodName]: { [StudentName]: Rank } }
 */
export const calculateHistoricalRanks = (students: StudentRecord[]) => {
  const allPeriods = Array.from(new Set(students.flatMap(s => s.history.map(h => h.period))));
  const periodRankMap: Record<string, Record<string, number>> = {};

  allPeriods.forEach(period => {
    const periodStudents = students
      .map(s => ({
        name: s.name,
        total: s.history.find(h => h.period === period)?.totalScore ?? -1
      }))
      .filter(s => s.total !== -1)
      .sort((a, b) => b.total - a.total);

    const ranks: Record<string, number> = {};
    periodStudents.forEach((s, idx) => {
      ranks[s.name] = idx + 1;
    });
    periodRankMap[period] = ranks;
  });

  return periodRankMap;
};

/**
 * 计算全周期、全科目的名次映射
 */
export const calculateSubjectHistoricalRanks = (students: StudentRecord[], subjects: string[]) => {
  const allPeriods = Array.from(new Set(students.flatMap(s => s.history.map(h => h.period))));
  const result: Record<string, Record<string, Record<string, number>>> = {};

  allPeriods.forEach(period => {
    result[period] = {};
    subjects.forEach(sub => {
      const subRanks: Record<string, number> = {};
      const sortedStudents = students
        .map(s => ({
          name: s.name,
          score: s.history.find(h => h.period === period)?.scores[sub] ?? -1
        }))
        .filter(s => s.score !== -1)
        .sort((a, b) => b.score - a.score);

      sortedStudents.forEach((s, idx) => {
        subRanks[s.name] = idx + 1;
      });
      result[period][sub] = subRanks;
    });
  });

  return result;
};

/**
 * 计算进退步系数
 * z = 2 * (x - y) / (x + y)
 * x: 第一次考试排名, y: 第二次考试排名
 */
export const calculateProgressCoefficient = (x: number, y: number): number => {
  if (x <= 0 || y <= 0) return 0;
  const z = (2 * (x - y)) / (x + y);
  return parseFloat(z.toFixed(2));
};

/**
 * 获取进退步分析全量数据
 */
export const getProgressAnalysisData = (
  students: StudentRecord[],
  periodX: string,
  periodY: string,
  allHistoricalRanks: Record<string, Record<string, number>>
) => {
  if (!periodX || !periodY) return [];

  const ranksX = allHistoricalRanks[periodX] || {};
  const ranksY = allHistoricalRanks[periodY] || {};

  return students.map(s => {
    const x = ranksX[s.name];
    const y = ranksY[s.name];

    // 如果某次考试缺考，则不参与计算
    if (x === undefined || y === undefined) return null;

    const coefficient = calculateProgressCoefficient(x, y);
    const rankChange = x - y; // 正数为进步（名次减小），负数为退步（名次增大）

    // 复用之前的连续进退步逻辑
    const streakInfo = calculateStreakInfo(s, allHistoricalRanks);
    let streakCount = 0;
    if (streakInfo && streakInfo.count > 0) {
      streakCount = streakInfo.type === 'improvement' ? streakInfo.count : -streakInfo.count;
    }

    return {
      name: s.name,
      class: s.class,
      rankX: x,
      rankY: y,
      rankChange,
      coefficient,
      streakCount
    };
  }).filter((d): d is NonNullable<typeof d> => d !== null);
};

/**
 * 计算每个考试周期的全校总分平均值
 */
export const calculateGradeAverages = (students: StudentRecord[]) => {
  const allPeriods = Array.from(new Set(students.flatMap(s => s.history.map(h => h.period))));
  const averages: Record<string, number> = {};

  allPeriods.forEach(period => {
    const periodTotals = students
      .map(s => s.history.find(h => h.period === period)?.totalScore)
      .filter((t): t is number => t !== undefined);

    if (periodTotals.length > 0) {
      averages[period] = periodTotals.reduce((a, b) => a + b, 0) / periodTotals.length;
    }
  });
  return averages;
};

/**
 * 获取特定考试周期的快照数据
 */
export const getPeriodSnapshot = (students: StudentRecord[], selectedPeriod: string, allHistoricalRanks: Record<string, Record<string, number>>) => {
  if (!selectedPeriod) return [];
  const ranks = allHistoricalRanks[selectedPeriod] || {};
  return students.map(s => {
    const historyItem = s.history.find(h => h.period === selectedPeriod);
    return {
      ...s,
      currentTotal: historyItem?.totalScore || 0,
      currentAverage: historyItem?.averageScore || 0,
      currentScores: historyItem?.scores || {},
      currentStatus: historyItem?.status,
      periodSchoolRank: ranks[s.name] || 9999
    };
  }).sort((a, b) => a.periodSchoolRank - b.periodSchoolRank);
};

/**
 * 计算上线分布（用于饼图）
 */
export const getAdmissionDistribution = (
  periodData: any[],
  thresholds: Record<string, number>,
  thresholdType: 'rank' | 'percent',
  labels: { key: string, color: string }[]
) => {
  if (!periodData.length) return [];

  // Check if any student has an imported status
  const hasImportedStatus = periodData.some(s => s.currentStatus);

  if (hasImportedStatus) {
    // Group by status strings found in data
    const statusCounts: Record<string, number> = {};
    periodData.forEach(s => {
      const status = s.currentStatus || '未上线';
      statusCounts[status] = (statusCounts[status] || 0) + 1;
    });

    // Try to match found statuses with defined labels for colors
    return Object.entries(statusCounts).map(([name, count]) => {
      const match = labels.find(l => l.key === name);
      return {
        name,
        value: count,
        color: match ? match.color : '#94a3b8'
      };
    }).sort((a, b) => b.value - a.value);
  }

  // Fallback to rank-based calculation
  const totalCount = periodData.length;
  const sortedThresholds = [...labels].map(l => ({
    ...l,
    limit: thresholdType === 'rank' 
      ? thresholds[l.key] 
      : Math.round((thresholds[l.key] / 100) * totalCount)
  })).sort((a, b) => a.limit - b.limit);

  const results = sortedThresholds.map((t, idx) => {
    const prevLimit = idx === 0 ? 0 : sortedThresholds[idx - 1].limit;
    const count = periodData.filter(s => s.periodSchoolRank > prevLimit && s.periodSchoolRank <= t.limit).length;
    return { name: t.key, value: count, color: t.color };
  });

  const lastLimit = sortedThresholds[sortedThresholds.length - 1].limit;
  results.push({
    name: '未上线',
    value: periodData.filter(s => s.periodSchoolRank > lastLimit).length,
    color: '#94a3b8'
  });

  return results.filter(r => r.value > 0);
};

/**
 * 计算单科平均分
 */
export const getSubjectAverages = (periodData: any[], subjects: string[]) => {
  return subjects.map(sub => {
    const avg = periodData.reduce((acc, s) => acc + (s.currentScores[sub] || 0), 0) / periodData.length;
    return { name: sub, avg: parseFloat(avg.toFixed(2)) };
  });
};

/**
 * 计算班级汇总统计
 */
export const getClassSummaries = (periodData: any[], selectedClasses: string[]) => {
  return selectedClasses.map(cls => {
    const clsStudents = periodData.filter(s => s.class === cls);
    const totalAvg = clsStudents.length > 0 
      ? clsStudents.reduce((acc, s) => acc + s.currentTotal, 0) / clsStudents.length 
      : 0;

    const top10Count = clsStudents.filter(s => s.periodSchoolRank <= 10).length;
    const top50Count = clsStudents.filter(s => s.periodSchoolRank <= 50).length;

    return {
      className: cls,
      count: clsStudents.length,
      average: parseFloat(totalAvg.toFixed(2)),
      top10: top10Count,
      top50: top50Count
    };
  });
};

/**
 * 获取班级荣誉榜（最高平均分、最多前10等）
 */
export const getClassLeaderboard = (classSummaries: any[]) => {
  if (classSummaries.length === 0) return null;
  return {
    highestAvg: [...classSummaries].sort((a, b) => b.average - a.average)[0],
    mostTop10: [...classSummaries].sort((a, b) => b.top10 - a.top10)[0],
    mostTop50: [...classSummaries].sort((a, b) => b.top50 - a.top50)[0],
  };
};

/**
 * 计算热力图最大值映射
 */
export const calculateHeatmapMaxValues = (data: any[], selectedClasses: string[]) => {
  const map: Record<string, number> = {};
  data.forEach(row => {
    const values = selectedClasses.map(cls => row[cls] || 0);
    map[row.name] = Math.max(...values);
  });
  return map;
};

/**
 * 计算特定学生的最新连续进退步状态
 */
export const calculateStreakInfo = (
  student: StudentRecord,
  allHistoricalRanks: Record<string, Record<string, number>>
) => {
  const history = student.history;
  const studentName = student.name;

  const rankList: number[] = history
    .map(h => allHistoricalRanks[h.period]?.[studentName])
    .filter((r): r is number => r !== undefined);

  if (rankList.length < 2) return null;

  const last = rankList[rankList.length - 1];
  const prev = rankList[rankList.length - 2];

  if (last === prev) return { count: 0, type: 'stable', totalChange: 0, steps: [] };

  const isImproving = last < prev;
  const type = isImproving ? 'improvement' : 'decline';

  let count = 0;
  let totalChange = 0;
  const steps: number[] = [];

  for (let i = rankList.length - 1; i > 0; i--) {
    const current = rankList[i];
    const previous = rankList[i - 1];
    const diff = previous - current;

    if ((isImproving && diff > 0) || (!isImproving && diff < 0)) {
      count++;
      totalChange += diff;
      steps.unshift(diff);
    } else {
      break;
    }
  }

  return { count, type, totalChange, steps };
};

/**
 * 计算考试参数（信度、区分度、难度等）
 */
export const calculateExamParameters = (periodData: any[], subjects: string[]) => {
  if (periodData.length === 0) return null;
  const n = periodData.length;
  const stats: any[] = [];

  subjects.forEach(sub => {
    const scores = periodData.map(s => s.currentScores[sub] || 0).sort((a, b) => a - b);
    const sum = scores.reduce((a, b) => a + b, 0);
    const mean = sum / n;
    const max = scores[n - 1];
    let fullScore = max > 120 ? (max > 150 ? Math.ceil(max / 10) * 10 : 150) : (max > 100 ? 120 : 100);
    const variance = scores.reduce((a, b) => a + Math.pow(b - mean, 2), 0) / n;
    const stdDev = Math.sqrt(variance);
    const median = n % 2 === 0 ? (scores[n/2 - 1] + scores[n/2]) / 2 : scores[Math.floor(n/2)];

    const counts: Record<number, number> = {};
    scores.forEach(s => counts[s] = (counts[s] || 0) + 1);
    let mode = scores[0];
    let maxCount = 0;
    Object.entries(counts).forEach(([val, count]) => { if (count > maxCount) { maxCount = count; mode = Number(val); } });

    const difficulty = mean / fullScore;
    const splitIdx = Math.round(n * 0.27);
    const top27 = scores.slice(n - splitIdx);
    const bottom27 = scores.slice(0, splitIdx);
    const meanTop = top27.length > 0 ? top27.reduce((a, b) => a + b, 0) / top27.length : 0;
    const meanBottom = bottom27.length > 0 ? bottom27.reduce((a, b) => a + b, 0) / bottom27.length : 0;
    const discrimination = (meanTop - meanBottom) / fullScore;

    stats.push({
      subject: sub,
      participants: n,
      max,
      mean: parseFloat(mean.toFixed(2)),
      stdDev: parseFloat(stdDev.toFixed(2)),
      mode,
      median,
      difficulty: parseFloat(difficulty.toFixed(2)),
      discrimination: parseFloat(discrimination.toFixed(2)),
      variance
    });
  });

  const k = subjects.length;
  const sumVarItems = stats.reduce((acc, s) => acc + s.variance, 0);
  const totalScores = periodData.map(s => s.currentTotal);
  const meanTotal = totalScores.reduce((a, b) => a + b, 0) / n;
  const varTotal = totalScores.reduce((a, b) => a + Math.pow(b - meanTotal, 2), 0) / n;
  const reliability = k > 1 ? (k / (k - 1)) * (1 - (sumVarItems / varTotal)) : 1;

  return { subjectStats: stats, reliability: parseFloat(reliability.toFixed(2)) };
};

/**
 * 获取学生雷达图数据
 */
export const getStudentRadarData = (
  student: StudentRecord,
  selectedPeriod: string,
  subjects: string[],
  radarBaseline: 'class' | 'grade',
  periodData: any[]
) => {
  const currentScores = student.history.find(h => h.period === selectedPeriod)?.scores || {};
  const baselineSource = radarBaseline === 'class' 
    ? periodData.filter(s => s.class === student.class)
    : periodData;

  return subjects.map(sub => {
    const studentScore = currentScores[sub] || 0;
    const baselineAvg = baselineSource.length > 0
      ? baselineSource.reduce((acc, s) => acc + (s.currentScores?.[sub] || 0), 0) / baselineSource.length
      : 0;

    return {
      subject: sub,
      score: studentScore,
      baseline: parseFloat(baselineAvg.toFixed(1)),
      fullMark: 150
    };
  });
};

/**
 * 获取学生单科历史名次趋势
 */
export const getStudentSubjectTrend = (
  student: StudentRecord,
  subject: string,
  allSubjectRanks: Record<string, Record<string, Record<string, number>>>
) => {
  return student.history.map(h => ({
    period: h.period,
    rank: allSubjectRanks[h.period]?.[subject]?.[student.name] || null
  })).filter(d => d.rank !== null);
};

/**
 * 获取上线类别
 */
export const getAdmissionCategory = (
  rank: number,
  thresholds: Record<string, number>,
  thresholdType: 'rank' | 'percent',
  totalStudents: number,
  snapshotStatus?: string
) => {
  // If status was explicitly imported, use it
  if (snapshotStatus) return snapshotStatus;

  const lines = [
    { key: '清北', label: '清北' },
    { key: 'C9', label: 'C9' },
    { key: '高分数', label: '高分' },
    { key: '名校', label: '名校' },
    { key: '特控', label: '特控' },
  ];

  for (const line of lines) {
    const limit = thresholdType === 'rank' 
      ? thresholds[line.key] 
      : Math.round((thresholds[line.key] / 100) * totalStudents);

    if (rank <= limit) return line.label;
  }
  return '未上线';
};

/**
 * 获取单科排名等级
 */
export const getSubjectRankCategory = (
  rank: number,
  thresholds: Record<string, number>,
  thresholdType: 'rank' | 'percent',
  totalStudents: number
) => {
  const categories = [
    { key: '清北', type: 'king' },
    { key: 'C9', type: 'elite' },
    { key: '高分数', type: 'high' },
    { key: '名校', type: 'standard' },
    { key: '特控', type: 'pass' },
  ];

  for (const cat of categories) {
    const limit = thresholdType === 'rank' 
      ? thresholds[cat.key] 
      : Math.round((thresholds[cat.key] / 100) * totalStudents);

    if (rank <= limit) return cat.type;
  }
  return 'fail';
};

/**
 * 计算单科名次分布
 */
export const getSubjectDistribution = (
  selectedPeriod: string,
  selectedSubject: string,
  selectedClasses: string[],
  periodData: any[],
  allSubjectRanks: Record<string, Record<string, Record<string, number>>>,
  thresholds: Record<string, number>,
  thresholdType: 'rank' | 'percent',
  totalStudents: number
) => {
  if (!selectedPeriod || !selectedSubject) return [];

  const subjectRanks = allSubjectRanks[selectedPeriod]?.[selectedSubject] || {};
  const filteredStudents = periodData.filter(s => selectedClasses.includes(s.class));

  const getLimit = (key: string) => {
    if (key === '未上线') return Infinity;
    return thresholdType === 'rank' 
      ? thresholds[key] 
      : Math.round((thresholds[key] / 100) * totalStudents);
  };

  const limits = {
    '清北': getLimit('清北'),
    'C9': getLimit('C9'),
    '高分数': getLimit('高分数'),
    '名校': getLimit('名校'),
    '特控': getLimit('特控'),
    '未上线': Infinity
  };

  const results = [
    { name: '清北线', count: 0, color: '#a855f7' },
    { name: 'C9线', count: 0, color: '#22c55e' },
    { name: '高分线', count: 0, color: '#3b82f6' },
    { name: '名校线', count: 0, color: '#94a3b8' },
    { name: '特控线', count: 0, color: '#eab308' },
    { name: '未上线', count: 0, color: '#ef4444' },
  ];

  filteredStudents.forEach(s => {
    const rank = subjectRanks[s.name];
    if (!rank) return;

    if (rank <= limits['清北']) results[0].count++;
    else if (rank <= limits['C9']) results[1].count++;
    else if (rank <= limits['高分数']) results[2].count++;
    else if (rank <= limits['名校']) results[3].count++;
    else if (rank <= limits['特控']) results[4].count++;
    else results[5].count++;
  });

  return results;
};

/**
 * 获取未上线学生列表
 */
export const getBelowLineStudents = (
  selectedPeriod: string,
  selectedSubject: string,
  selectedClasses: string[],
  periodData: any[],
  allSubjectRanks: Record<string, Record<string, Record<string, number>>>,
  teKongLimit: number
) => {
  if (!selectedPeriod || !selectedSubject) return [];

  const subjectRanks = allSubjectRanks[selectedPeriod]?.[selectedSubject] || {};

  return periodData
    .filter(s => selectedClasses.includes(s.class))
    .filter(s => {
      const rank = subjectRanks[s.name];
      return rank && rank > teKongLimit;
    })
    .map(s => ({
      name: s.name,
      rank: subjectRanks[s.name],
      class: s.class
    }))
    .sort((a, b) => a.rank - b.rank);
};

