import React, { useState, useEffect, useMemo } from 'react';
import { Database, Plus, Trash2, GripVertical, AlertTriangle, CheckCircle2, FileSpreadsheet, Layers, Users, TrendingUp, Award, Info, X, BarChart, ChevronRight } from 'lucide-react';
import { ExamEntity } from '../types';
import { useAnalysis } from '../context/AnalysisContext';
import ImportWizard from './ImportWizard';

const DataManager: React.FC = () => {
  const { data: initialData, setData: onDataUpdated } = useAnalysis();
  const [showWizard, setShowWizard] = useState(false);
  const [draggedIndex, setDraggedIndex] = useState<number | null>(null);
  const [selectedExamName, setSelectedExamName] = useState<string | null>(null);

  const [exams, setExams] = useState<ExamEntity[]>([]);

  useEffect(() => {
    if (!initialData || initialData.students.length === 0) {
      setExams([]);
      setSelectedExamName(null);
      return;
    }
    const allPeriods = Array.from(new Set(initialData.students.flatMap(s => s.history.map(h => h.period))));

    const examEntities: ExamEntity[] = allPeriods.map((period, idx) => {
      const representative = initialData.students.find(s => s.history.some(h => h.period === period))
        ?.history.find(h => h.period === period);

      return {
        id: `exam-${period}-${idx}`,
        name: period,
        weight: idx,
        isComplete: representative?.isComplete ?? true,
        fileCount: 1
      };
    });

    setExams(examEntities);

    if (!selectedExamName && examEntities.length > 0) {
      setSelectedExamName(examEntities[examEntities.length - 1].name);
    }
  }, [initialData]);

  const updateGlobalOrder = (newExams: ExamEntity[]) => {
    if (!initialData) return;
    const periodOrder = newExams.map(e => e.name);
    const updatedStudents = initialData.students.map(student => ({
      ...student,
      history: [...student.history].sort((a, b) => 
        periodOrder.indexOf(a.period) - periodOrder.indexOf(b.period)
      )
    }));
    onDataUpdated({ ...initialData, students: updatedStudents });
  };

  const handleDragStart = (index: number) => setDraggedIndex(index);
  const handleDragOver = (e: React.DragEvent, index: number) => e.preventDefault();

  const handleDrop = (index: number) => {
    if (draggedIndex === null || draggedIndex === index) return;
    const newExams = [...exams];
    const [movedItem] = newExams.splice(draggedIndex, 1);
    newExams.splice(index, 0, movedItem);
    setExams(newExams);
    setDraggedIndex(null);
    updateGlobalOrder(newExams);
  };

  const handleDeleteExam = (examName: string, e: React.MouseEvent) => {
    e.stopPropagation();
    if (!confirm(`⚠️ Warning: You are about to permanently delete all data related to "${examName}". Are you sure?`)) return;
    if (!initialData) return;

    const newStudents = initialData.students.map(s => ({
      ...s,
      history: s.history.filter(h => h.period !== examName)
    })).filter(s => s.history.length > 0);

    if (selectedExamName === examName) setSelectedExamName(null);

    if (newStudents.length === 0) {
      onDataUpdated(null);
    } else {
      onDataUpdated({
        ...initialData,
        students: newStudents,
        classes: [...new Set(newStudents.map(s => s.class))],
        subjects: [...new Set(newStudents.flatMap(s => Object.keys(s.history[0]?.scores || {})))]
      });
    }
  };

  const selectedExamStats = useMemo(() => {
    if (!selectedExamName || !initialData) return null;
    const periodStudents = initialData.students
      .map(s => {
        const historyItem = s.history.find(h => h.period === selectedExamName);
        return historyItem ? { ...s, historyItem } : null;
      })
      .filter((s): s is NonNullable<typeof s> => s !== null);

    if (periodStudents.length === 0) return null;
    const totals = periodStudents.map(s => s.historyItem.totalScore);
    return {
      name: selectedExamName,
      participants: periodStudents.length,
      average: (totals.reduce((a, b) => a + b, 0) / totals.length).toFixed(2),
      highest: Math.max(...totals),
      topStudentName: periodStudents.find(s => s.historyItem.totalScore === Math.max(...totals))?.name || 'N/A',
      subjects: Object.keys(periodStudents[0].historyItem.scores),
      classes: [...new Set(periodStudents.map(s => s.class))]
    };
  }, [selectedExamName, initialData]);

  return (
    <div className="max-w-6xl mx-auto space-y-6 pb-20 animate-in fade-in duration-500">
      <div className="flex items-center justify-between">
        <div>
          <h2 className="text-2xl font-black text-gray-900">Exam Data Management</h2>
          <p className="text-sm text-gray-500">Import and organize your academic records.</p>
        </div>
        {!showWizard && (
          <button onClick={() => setShowWizard(true)} className="bg-blue-600 text-white px-6 py-2.5 rounded-xl font-bold flex items-center gap-2 shadow-lg hover:scale-105 transition-all">
            <Plus className="w-5 h-5" /> Import New Data
          </button>
        )}
      </div>

      {showWizard ? (
        <ImportWizard onComplete={(s) => { onDataUpdated(s); setShowWizard(false); }} onCancel={() => setShowWizard(false)} currentData={initialData} />
      ) : (
        <div className="grid grid-cols-1 lg:grid-cols-12 gap-6">
          <div className="lg:col-span-7 space-y-4">
            {exams.length === 0 ? (
              <div className="bg-white border-2 border-dashed border-gray-200 rounded-3xl p-20 text-center space-y-4">
                <FileSpreadsheet className="w-10 h-10 text-blue-600 mx-auto" />
                <h3 className="text-lg font-bold text-gray-800">No Data Imported</h3>
                <button onClick={() => setShowWizard(true)} className="text-blue-600 font-bold hover:underline">Launch Import Wizard</button>
              </div>
            ) : (
              <div className="bg-white rounded-3xl border border-gray-100 shadow-sm overflow-hidden divide-y divide-gray-50">
                {exams.map((exam, index) => (
                  <div key={exam.id} draggable onDragStart={() => handleDragStart(index)} onDragOver={(e) => handleDragOver(e, index)} onDrop={() => handleDrop(index)} onClick={() => setSelectedExamName(exam.name)} className={`p-4 hover:bg-gray-50 transition-colors flex items-center justify-between group cursor-pointer ${selectedExamName === exam.name ? 'bg-blue-50/50 border-l-4 border-l-blue-600' : ''}`}>
                    <div className="flex items-center gap-4">
                      <GripVertical className="w-5 h-5 text-gray-400 cursor-grab" />
                      <div className={`w-10 h-10 rounded-xl flex items-center justify-center text-xs font-black ${selectedExamName === exam.name ? 'bg-blue-600 text-white' : 'bg-gray-100 text-gray-400'}`}>{index + 1}</div>
                      <div>
                        <h4 className="font-bold text-gray-800 flex items-center gap-2">{exam.name}{exam.isComplete && <CheckCircle2 className="w-3.5 h-3.5 text-green-500" />}</h4>
